                print(f"  - {e}")
        if efeito_sim is not None:
            print(f"Efeito simulado no fechamento de {competencia_texto(efeito_sim['competencia'])} (fechamento refeito numa pasta "
                  f"temporária com a regra proposta; nada gravado):")
